def execute_command(image) -> ImagePatch:
    image_patch = ImagePatch(image)
    man_patches = image_patch.find("man")
    phone_patches = image_patch.find("phone")

    if not man_patches or not phone_patches:
        return image_patch

    man_centers = [(p.left + p.right) / 2 for p in man_patches]
    phone_centers = [(p.left + p.right) / 2 for p in phone_patches]

    min_distance = float('inf')
    closest_man_phone_pair = None

    for man_center in man_centers:
        for phone_center in phone_centers:
            dist = abs(man_center - phone_center)
            if dist < min_distance:
                min_distance = dist
                closest_man_phone_pair = (man_center, phone_center)

    if closest_man_phone_pair:
        man_center, phone_center = closest_man_phone_pair
        if man_center < phone_center:
            return man_patches[man_centers.index(man_center)]
        else:
            return phone_patches[phone_centers.index(phone_center)]

    return image_patch

